<?php
declare(strict_types=1);
function v26_video_action(string $action,array $u,array $b):array {
 $uid=(int)$u['id'];
 if($action==='v26_video_list')return $u['role']==='admin'?query("SELECT r.*,u.name FROM ep_records r JOIN ep_users u ON u.id=r.user_id WHERE r.module='video_receipt'".(empty($_GET['employee73'])?'':' AND r.user_id=?')." ORDER BY r.id DESC",empty($_GET['employee73'])?[]:[(int)$_GET['employee73']])->fetchAll():query("SELECT * FROM ep_records WHERE user_id=? AND module='video_receipt' AND status<>'draft' ORDER BY id DESC",[$uid])->fetchAll();
 if($action==='v26_video_create'){
  admin_only($u);$staff=employee_required((int)$b['user_id']);$mode=(string)($b['mode']??'');$source=(int)($b['source_id']??0);$kind=(string)($b['source_kind']??'');$text=trim((string)($b['text']??''));$snapshot=null;
  if($mode==='automatic'){
   if(!in_array($kind,['payroll','leave_cash'],true))fail('حدد نوع العملية');$r=query($kind==='payroll'?'SELECT * FROM ep_payroll WHERE id=? AND user_id=?':'SELECT * FROM ep_records WHERE id=? AND user_id=?',[$source,$staff['id']])->fetch();if(!$r||$r['status']!=='approved'||($kind==='leave_cash'&&$r['module']!=='leave_cash'))fail('عملية معتمدة مطلوبة');$paid=0.0;foreach(query("SELECT * FROM ep_records WHERE user_id=? AND module='payment' AND status='approved'",[$staff['id']])->fetchAll()as $payment){$pv=decode($payment['body_json']);if(($pv['kind']??'')===$kind&&(int)$pv['source_id']===$source)$paid+=(float)$payment['amount'];if($kind==='payroll'&&($pv['kind']??'')==='bank'){$bank=query('SELECT snapshot_json FROM ep_bank_payroll WHERE id=?',[(int)$pv['source_id']])->fetch();if($bank&&(int)(decode($bank['snapshot_json'])['payroll_id']??0)===$source)$paid+=min((float)$payment['amount'],max(0,(float)$r['net_amount']-$paid));}}if($kind==='leave_cash')$paid=v26_leave_paid_amounts((int)$staff['id'])[$source]??0;if($paid<=0)fail('سجل الدفع الفعلي قبل إنشاء نص الاستلام التلقائي');$snapshot=$r;$text='أنا '.$staff['name'].' أقر باستلام مبلغ '.number_format($paid,3,'.','').' دينار كويتي عن '.($kind==='payroll'?'مستحقات شهر '.$r['month_key']:'صرف رصيد إجازات بتاريخ '.$r['date_from']).'. هذا الإقرار يخص العملية المحددة فقط.';if($kind==='payroll'){$c=decode($r['calculation_json']);$text.=' الراتب الأساسي '.number_format((float)$c['salary'],3,'.','').' د.ك، والمستحقات الإضافية '.number_format((float)$c['addition'],3,'.','').' د.ك، والخصومات '.number_format((float)$c['deduction'],3,'.','').' د.ك.';};
  }elseif($mode!=='custom')fail('نوع الإقرار غير صالح');
  if(!$text||mb_strlen($text)>15000)fail('النص مطلوب وفي حدود15000 حرف');$id=v26_insert('video_receipt',(int)$staff['id'],local_time()->format('Y-m-d'),null,['mode'=>$mode,'text'=>$text,'source_kind'=>$kind,'source_id'=>$source,'snapshot'=>$snapshot,'financial'=>$mode==='automatic'||filter_var($b['financial']??false,FILTER_VALIDATE_BOOLEAN),'author'=>$uid],'draft');audit('video_receipt_create','receipt:'.$id,['text'=>$text,'mode'=>$mode,'source_id'=>$source]);return ['id'=>$id,'text'=>$text];
 }
 if($action==='v26_video_send'){admin_only($u);db()->beginTransaction();$r=query("SELECT * FROM ep_records WITH (UPDLOCK, HOLDLOCK) WHERE id=? AND module='video_receipt'",[(int)$b['id']])->fetch();if(!$r||$r['status']!=='draft')fail('الإقرار أرسل بالفعل');$v=decode($r['body_json']);$v['sent_at']=utc_now();$v['sent_by']=$uid;query("UPDATE ep_records SET status='sent',body_json=?,updated_at=? WHERE id=?",[jencode($v),utc_now(),$r['id']]);notice((int)$r['user_id'],'إقرار استلام مطلوب','افتح شاشة إقراراتي بالفيديو — رقم الإقرار '.$r['id'],true,['category'=>'administration','type'=>'video','screen'=>'video_receipt','record_id'=>(int)$r['id'],'sender'=>$uid,'batch'=>bin2hex(random_bytes(12))]);audit('video_receipt_sent','receipt:'.$r['id'],['user_id'=>$r['user_id']]);db()->commit();return ['ok'=>true];}
 $id=(int)($b['id']??$_GET['id']??0);$r=query("SELECT * FROM ep_records WHERE id=? AND module='video_receipt'",[$id])->fetch();if(!$r||($u['role']!=='admin'&&(int)$r['user_id']!==$uid)||($u['role']!=='admin'&&$r['status']==='draft'))fail('الإقرار غير متاح',403);
 if($action==='v26_video_detail'){if($r['file_id'])$r['media_url']='file.php?id='.(int)$r['file_id'];$r['can_download']=$u['role']==='admin'&&!empty($u['full_supervisor31']);$r['recorded_at']=decode($r['body_json'])['recorded_at']??null;return $r;}
 if($action==='v26_video_ticket'){if((int)$r['user_id']!==$uid||$r['status']!=='sent')fail('التسجيل غير متاح');$nonce=bin2hex(random_bytes(32));$_SESSION['video_ticket']=['id'=>$id,'nonce'=>$nonce,'issued'=>time()];return ['nonce'=>$nonce,'expires_in'=>900];}
 if($action==='v26_video_objection'){db()->beginTransaction();$r=query("SELECT * FROM ep_records WITH (UPDLOCK, HOLDLOCK) WHERE id=? AND module='video_receipt'",[$id])->fetch();if((int)$r['user_id']!==$uid||$r['status']!=='sent')fail('غير متاح');$note=trim((string)($b['note']??''));if(!$note)fail('وضح الاعتراض');$v=decode($r['body_json']);$v['objection']=$note;$v['objection_at']=utc_now();query("UPDATE ep_records SET status='objection',body_json=?,updated_at=? WHERE id=?",[jencode($v),utc_now(),$id]);audit('receipt_objection','receipt:'.$id,['note'=>$note]);db()->commit();return ['ok'=>true];}
 if($action==='v26_video_upload'){
  $ticket=$_SESSION['video_ticket']??[];if((int)$r['user_id']!==$uid||$r['status']!=='sent'||($ticket['id']??0)!==$id||!hash_equals($ticket['nonce']??'',(string)($b['nonce']??''))||time()-($ticket['issued']??0)>900)fail('جلسة التسجيل انتهت');if(empty($b['confirm_received']))fail('أكد استلام العملية فعلًا أو قدم اعتراضًا');$f=$_FILES['video']??null;if(!$f||$f['error']!==UPLOAD_ERR_OK||!is_uploaded_file($f['tmp_name'])||$f['size']<100||$f['size']>64*1024*1024)fail('الفيديو غير صالح أو أكبر من64MB');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$types=['video/webm'=>'webm','video/mp4'=>'mp4','video/quicktime'=>'mov'];if(!isset($types[$mime]))fail('صيغة الفيديو غير مدعومة');$disk=bin2hex(random_bytes(24)).'.'.$types[$mime];$path=EP_ROOT.'/private/files/'.$disk;
  db()->beginTransaction();$locked=query('SELECT * FROM ep_records WITH (UPDLOCK, HOLDLOCK) WHERE id=?',[$id])->fetch();if($locked['status']!=='sent')fail('الإقرار سجل بالفعل');if(!move_uploaded_file($f['tmp_name'],$path))fail('تعذر حفظ الفيديو');try{query('INSERT INTO ep_files(user_id,disk_name,original_name,mime,size_bytes,sha256,created_at) VALUES(?,?,?,?,?,?,?)',[$uid,$disk,'receipt.'.$types[$mime],$mime,filesize($path),hash_file('sha256',$path),utc_now()]);$fid=(int)db()->lastInsertId();$v=decode($r['body_json']);$v['recorded_at']=utc_now();$v['recorded_by']=$uid;$v['sha256']=hash_file('sha256',$path);query("UPDATE ep_records SET file_id=?,status='recorded',body_json=?,updated_at=? WHERE id=?",[$fid,jencode($v),utc_now(),$id]);audit('video_receipt_recorded','receipt:'.$id,['file_id'=>$fid,'sha256'=>$v['sha256']]);db()->commit();unset($_SESSION['video_ticket']);}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();@unlink($path);throw $e;}return ['ok'=>true,'id'=>$id];
 }
 fail('عملية إقرار غير صالحة',404);
}
